        if ('A' <= c && c <= 'M') north++;
        else if ('N' <= c && c <= 'Z') south++;
        else if ('a' <= c && c <= 'm') east++;
        else if ('n' <= c && c <= 'z') west++;
    }

    int v = north - south; // positive => north, negative => south
    int h = east - west;   // positive => east, negative => west

    char ans[100005];
    int len = 0;

    if (v > 0) {
        for (int i = 0; i < v; i++) ans[len++] = 'A'; // any A-M works
    } else {
        for (int i = 0; i < -v; i++) ans[len++] = 'N'; // any N-Z works
    }

    if (h > 0) {
        for (int i = 0; i < h; i++) ans[len++] = 'a'; // any a-m works
    } else {
        for (int i = 0; i < -h; i++) ans[len++] = 'n'; // any n-z works
    }

    ans[len] = '\0';

    printf("%d\n", len);
    printf("%s\n", ans);

    return 0;
