    vertical = north - south
    horizontal = east - west

    res = []
    if vertical > 0:
        res.extend('A' * vertical)   # any A-M works for North
    elif vertical < 0:
        res.extend('N' * (-vertical))  # any N-Z works for South

    if horizontal > 0:
        res.extend('a' * horizontal)   # any a-m works for East
    elif horizontal < 0:
        res.extend('n' * (-horizontal))  # any n-z works for West

    ans = ''.join(res)
